/**
 * One admitted format: its media type and the extensions that name it.
 */
export type AttachmentFormatRecord = {
  media_type: string;
  /**
   * Lowercase, each with its leading dot, e.g. '.pdf'.
   */
  extensions: string[];
};

/**
 * The limits every conversation's attachments are held to, and the formats.
 */
export type AttachmentPolicyResponse = {
  max_file_bytes: number;
  max_files_per_conversation: number;
  max_total_bytes_per_conversation: number;
  formats: AttachmentFormatRecord[];
};

/**
 * How one question is answered.
 *
 * `choice` offers a bounded set of declared options and admits exactly one of
 * them verbatim as its answer; `text` admits free prose up to
 * `MAX_ANSWER_CHARS`. The two exhaust the vocabulary: a kind the renderer does
 * not know is a question it cannot render, so the set is closed.
 */
export type ClarificationKind = "choice" | "text";

/**
 * One bounded question inside a clarification request.
 *
 * `options` belongs to `choice` and only to `choice`: a text question carrying
 * options would advertise a constraint the answer path does not enforce, and a
 * choice without options would offer nothing to choose. Both are refused at
 * construction rather than tolerated and interpreted downstream.
 */
export type ClarificationQuestion = {
  id: string;
  prompt: string;
  kind: ClarificationKind;
  options?: string[] | null;
  required?: boolean;
};

/**
 * One model's licence, as its lane's catalog states it, with the text.
 *
 * `spdx`, `name` and `digest` are the catalog entry's `licence`; `digest` is
 * `sha256:` and the hex SHA-256 of `text` encoded as UTF-8. `installed` is the
 * entry's own.
 */
export type ModelLicenceResponse = {
  provider: Provider;
  transport: ProviderTransport;
  model: string;
  installed: boolean;
  spdx: string | null;
  name: string;
  digest: string;
  text: string;
};

/**
 * Canonical product identities shared by requests and configuration.
 */
export type Provider =
  | "claude"
  | "codex"
  | "antigravity"
  | "kimi"
  | "zai"
  | "zhipu"
  | "deepseek"
  | "moonshot"
  | "minimax"
  | "qwen"
  | "ollama"
  | "llamacpp";

/**
 * Why a provider failed, in terms a client can act on.
 *
 * The value is the wire form: lowercase, underscore-separated, and stable.
 */
export type ProviderCondition =
  | "network_unreachable"
  | "provider_overloaded"
  | "unauthenticated"
  | "throttled"
  | "usage_exhausted"
  | "credits_exhausted"
  | "budget_exhausted"
  | "invalid_request"
  | "model_does_not_fit"
  | "no_answer"
  | "unknown";

/**
 * How a run reaches a named provider product.
 */
export type ProviderTransport = "api" | "cli";

/**
 * One skill with the whole text of its `SKILL.md`.
 */
export type SkillDetailRecord = {
  name: string;
  description: string;
  /**
   * The skill's parsed selection predicate, without the keys it leaves unset;
   * null when it declares none.
   */
  applies_when: { [key: string]: unknown } | null;
  digest: string;
  /**
   * Every file of the skill, SKILL.md included, in path order.
   */
  files: SkillFileRecord[];
  /**
   * SKILL.md as written, front matter included.
   */
  content: string;
};

/**
 * One file of a skill: its path within the skill, size and digest.
 */
export type SkillFileRecord = {
  /**
   * Relative to the skill's directory, '/'-separated.
   */
  path: string;
  /**
   * The file's size in UTF-8 bytes.
   */
  bytes: number;
  digest: string;
};

/**
 * One thing a check found in a skill.
 */
export type SkillFindingRecord = {
  severity: "error" | "warning";
  code: string;
  message: string;
  /**
   * The file the finding is about, relative to the skill; null for the skill
   * as a whole.
   */
  path: string | null;
};

/**
 * Every skill of the package, ordered by name, and the set's revision.
 */
export type SkillListResponse = {
  revision: string;
  skills: SkillRecord[];
};

/**
 * One skill: what it is, when it applies, and the files it is made of.
 */
export type SkillRecord = {
  name: string;
  description: string;
  /**
   * The skill's parsed selection predicate, without the keys it leaves unset;
   * null when it declares none.
   */
  applies_when: { [key: string]: unknown } | null;
  digest: string;
  /**
   * Every file of the skill, SKILL.md included, in path order.
   */
  files: SkillFileRecord[];
};

/**
 * What checking one skill found; `valid` is false if any finding is an error.
 */
export type SkillVerificationRecord = {
  name: string;
  digest: string;
  valid: boolean;
  findings: SkillFindingRecord[];
};

/**
 * Durable lifecycle states for a run.
 */
export type ThreadStatus =
  | "submitted"
  | "running"
  | "input_required"
  | "cancelling"
  | "cancelled"
  | "completed"
  | "failed"
  | "archived"
  | "repair_needed"
  | "reconciling"
  | "deleting";

/**
 * Lifecycle states for a single tool invocation.
 */
export type ToolCallStatus = "pending" | "in_progress" | "completed" | "failed";

/**
 * ACP tool categories (mirrors agentclientprotocol.com schema).
 */
export type ToolKind =
  | "read"
  | "edit"
  | "delete"
  | "move"
  | "search"
  | "execute"
  | "think"
  | "fetch"
  | "switch_mode"
  | "other";
